import sympy
import math

# Top-level setup
# The witness is expected to be a tuple (s, p, q) or a dictionary with keys 's', 'p', 'q'.
# These integers represent objects in the ring of integers Z:
# - R = Z (the ring of integers, a commutative ring with identity)
# - S = {s^k | k >= 0} (multiplicatively closed subset generated by s)
# - P = (p) (prime ideal generated by p)
# - Q = (q) (ideal generated by q)
x, y = sympy.symbols('x y')

def conditions(witness) -> list[bool]:
    try:
        if isinstance(witness, dict):
            s = witness.get('s', witness.get('S', witness.get('s_gen')))
            p = witness.get('p', witness.get('P', witness.get('p_gen')))
            q = witness.get('q', witness.get('Q', witness.get('q_gen')))
        else:
            s, p, q = witness
            
        s = int(s)
        p = int(p)
        q = int(q)
    except Exception:
        return [False, False, False, False]

    # H_1: R is a commutative ring with identity
    # We are working in the ring of integers Z, which is a commutative ring with identity.
    h1_ok = True

    # H_2: S is a multiplicatively closed subset of R
    # S is generated by s, i.e., S = {s^k | k >= 0}, which is multiplicatively closed.
    h2_ok = True

    # H_3: The prime ideal P is disjoint from S (P \cap S = \emptyset)
    try:
        # P is generated by p. It is prime if |p| is prime or p == 0.
        is_prime = sympy.isprime(abs(p)) or p == 0
        
        # S = {s^k | k >= 0}. P intersects S iff s^k is a multiple of p for some k.
        # If p == 0, P = {0}. 0 in S iff s == 0.
        # If p != 0, since p is prime, p divides s^k iff p divides s.
        if p == 0:
            disjoint = (s != 0)
        else:
            disjoint = (s % p != 0)
            
        h3_ok = bool(is_prime and disjoint)
    except Exception:
        h3_ok = False

    # ¬Q: The contraction of the extended ideal (S^{-1}Q)^c in R is not equal to Q
    try:
        # Q is generated by q.
        # The contraction (S^{-1}Q)^c in Z is generated by q / gcd(q, s^\infty).
        # It equals Q iff gcd(q, s) == 1 (for q != 0).
        # If q == 0, contraction is {0} = Q iff s != 0.
        if q == 0:
            conclusion = (s != 0)
        else:
            conclusion = (math.gcd(abs(q), abs(s)) == 1)
            
        neg_q_ok = not conclusion
    except Exception:
        neg_q_ok = False

    return [h1_ok, h2_ok, h3_ok, neg_q_ok]

CONDITION_LABELS = [
    "H_1: R is a commutative ring with identity",
    "H_2: S is a multiplicatively closed subset of R",
    "H_3: The prime ideal P is disjoint from S (P ∩ S = ∅)",
    "¬Q: The contraction of the extended ideal (S^{-1}Q)^c in R is not equal to Q"
]

N_HYP = 3
NEG_Q_INDEX = 3